INSERT INTO tp_exams (exam_code, kind, title, subtitle, description, difficulty, time_limit_sec, status, created_by) VALUES
('TP-PRACTICE-2026-SET09','PRACTICE','TOEFL iBT Practice — Set 09 (Full-Length 2026 Format, Practice-Test Calibrated)','Reading 50 · Listening 47 · Writing 12 · Speaking 11','A full-length set on the January 2026 TOEFL iBT structure (90 minutes, 120 items). Text length, vocabulary level, task design, and option style were calibrated against the published ETS practice tests: Complete the Words in paragraph context, everyday texts with two or three questions each, 200-word academic passages with five questions, short conversations with two questions, and Build a Sentence replies. The published ETS practice tests contain 40, 34, 12, and 11 items per section; this set keeps the 50, 47, 12, and 11 rows of TestPrep sets 02-08. Every text, script, question, and option was newly written for TestPrep; no ETS material is reproduced. Auto-scored items return a TestPrep internal band estimate, not an official ETS score.',NULL,5400,'PUBLISHED','admin');
INSERT INTO tp_questions (exam_id, section, task_type, prompt, body_text, audio_mode, choices_json, answer_key, auto_score, explanation, order_no) VALUES
(@set09_exam_id,'READING','COMPLETE_THE_WORDS','Fill in the missing letters in the paragraph. Word (1): orga_ _ _ _ _','Fermentation is one of the oldest techniques that humans have employed to preserve food. Tiny (1) orga_ _ _ _ _ consume (2) nat_ _ _ _ sugars (3) a_ _ gradually (4) deco_ _ _ _ _ them (5) in_ _ acids, gases, or alcohol. Because these acids prevent harmful bacteria from multiplying, fermented products such as cheese, soy sauce, and pickled cabbage remain edible for months. The process also alters flavor and texture, which explains why many traditional cuisines depend on it. Researchers are now investigating whether fermented foods contribute to digestive health.','NONE','["nists","nisms","nized","nizer"]','B',1,'organisms — the subject of "consume" must be a plural noun for living things: "Tiny organisms consume natural sugars." Organists are musicians, and organized and organizer do not fit before a plural verb.',1),
(@set09_exam_id,'READING','COMPLETE_THE_WORDS','Fill in the missing letters in the paragraph. Word (2): nat_ _ _ _','Fermentation is one of the oldest techniques that humans have employed to preserve food. Tiny (1) orga_ _ _ _ _ consume (2) nat_ _ _ _ sugars (3) a_ _ gradually (4) deco_ _ _ _ _ them (5) in_ _ acids, gases, or alcohol. Because these acids prevent harmful bacteria from multiplying, fermented products such as cheese, soy sauce, and pickled cabbage remain edible for months. The process also alters flavor and texture, which explains why many traditional cuisines depend on it. Researchers are now investigating whether fermented foods contribute to digestive health.','NONE','["ural","ions","ives","ures"]','A',1,'natural — an adjective is needed before "sugars": natural sugars. Nations, natives, and natures are plural nouns and cannot describe "sugars".',2),
(@set09_exam_id,'READING','COMPLETE_THE_WORDS','Fill in the missing letters in the paragraph. Word (3): a_ _','Fermentation is one of the oldest techniques that humans have employed to preserve food. Tiny (1) orga_ _ _ _ _ consume (2) nat_ _ _ _ sugars (3) a_ _ gradually (4) deco_ _ _ _ _ them (5) in_ _ acids, gases, or alcohol. Because these acids prevent harmful bacteria from multiplying, fermented products such as cheese, soy sauce, and pickled cabbage remain edible for months. The process also alters flavor and texture, which explains why many traditional cuisines depend on it. Researchers are now investigating whether fermented foods contribute to digestive health.','NONE','["nd","re","ny","ll"]','A',1,'and — two verbs share one subject: organisms consume ... and gradually transform. Are, any, and all cannot join the two verbs.',3),
(@set09_exam_id,'READING','COMPLETE_THE_WORDS','Fill in the missing letters in the paragraph. Word (4): deco_ _ _ _ _','Fermentation is one of the oldest techniques that humans have employed to preserve food. Tiny (1) orga_ _ _ _ _ consume (2) nat_ _ _ _ sugars (3) a_ _ gradually (4) deco_ _ _ _ _ them (5) in_ _ acids, gases, or alcohol. Because these acids prevent harmful bacteria from multiplying, fermented products such as cheese, soy sauce, and pickled cabbage remain edible for months. The process also alters flavor and texture, which explains why many traditional cuisines depend on it. Researchers are now investigating whether fermented foods contribute to digestive health.','NONE','["rated","mpose","upled","ction"]','B',1,'decompose — to decompose something is to break it down into simpler substances: the sugars are broken down into acids, gases, or alcohol. Decorated and decoupled are past forms that cannot follow "and gradually" here, and a decoction is a noun.',4),
(@set09_exam_id,'READING','COMPLETE_THE_WORDS','Fill in the missing letters in the paragraph. Word (5): in_ _','Fermentation is one of the oldest techniques that humans have employed to preserve food. Tiny (1) orga_ _ _ _ _ consume (2) nat_ _ _ _ sugars (3) a_ _ gradually (4) deco_ _ _ _ _ them (5) in_ _ acids, gases, or alcohol. Because these acids prevent harmful bacteria from multiplying, fermented products such as cheese, soy sauce, and pickled cabbage remain edible for months. The process also alters flavor and texture, which explains why many traditional cuisines depend on it. Researchers are now investigating whether fermented foods contribute to digestive health.','NONE','["ch","fo","to","ns"]','C',1,'into — "decompose them into acids": the preposition into shows the result of a change. Inch, info, and inns are nouns.',5),
(@set09_exam_id,'READING','COMPLETE_THE_WORDS','Fill in the missing letters in the paragraph. Word (6): proje_ _ _ _ _','Every flat map of the world distorts the planet in some way. A (6) proje_ _ _ _ _ is (7) t_ _ mathematical (8) met_ _ _ that (9) conv_ _ _ _ the (10) cur_ _ _ surface of the globe into a flat image. Some projections preserve the shapes of continents but exaggerate the size of territories near the poles, which is why Greenland can appear as large as Africa. Others maintain accurate areas while bending coastlines. Consequently, navigators, educators, and statisticians select different projections according to their purposes.','NONE','["ctors","ction","ctile","cting"]','B',1,'projection — a singular noun is needed after "A", and the sentence defines the method of drawing the round Earth on a flat map. A projectile is something thrown or fired; projectors is plural; projecting is not a noun that "A" can introduce here.',6),
(@set09_exam_id,'READING','COMPLETE_THE_WORDS','Fill in the missing letters in the paragraph. Word (7): t_ _','Every flat map of the world distorts the planet in some way. A (6) proje_ _ _ _ _ is (7) t_ _ mathematical (8) met_ _ _ that (9) conv_ _ _ _ the (10) cur_ _ _ surface of the globe into a flat image. Some projections preserve the shapes of continents but exaggerate the size of territories near the poles, which is why Greenland can appear as large as Africa. Others maintain accurate areas while bending coastlines. Consequently, navigators, educators, and statisticians select different projections according to their purposes.','NONE','["oo","wo","ry","he"]','D',1,'the — an article is needed before "mathematical method": is the mathematical method. Too, two, and try do not fit before a singular noun phrase.',7),
(@set09_exam_id,'READING','COMPLETE_THE_WORDS','Fill in the missing letters in the paragraph. Word (8): met_ _ _','Every flat map of the world distorts the planet in some way. A (6) proje_ _ _ _ _ is (7) t_ _ mathematical (8) met_ _ _ that (9) conv_ _ _ _ the (10) cur_ _ _ surface of the globe into a flat image. Some projections preserve the shapes of continents but exaggerate the size of territories near the poles, which is why Greenland can appear as large as Africa. Others maintain accurate areas while bending coastlines. Consequently, navigators, educators, and statisticians select different projections according to their purposes.','NONE','["als","ers","eor","hod"]','D',1,'method — "the mathematical method that converts": a singular noun meaning a way of doing something. Metals and meters are plural, and a meteor has nothing to do with mathematics.',8),
(@set09_exam_id,'READING','COMPLETE_THE_WORDS','Fill in the missing letters in the paragraph. Word (9): conv_ _ _ _','Every flat map of the world distorts the planet in some way. A (6) proje_ _ _ _ _ is (7) t_ _ mathematical (8) met_ _ _ that (9) conv_ _ _ _ the (10) cur_ _ _ surface of the globe into a flat image. Some projections preserve the shapes of continents but exaggerate the size of territories near the poles, which is why Greenland can appear as large as Africa. Others maintain accurate areas while bending coastlines. Consequently, navigators, educators, and statisticians select different projections according to their purposes.','NONE','["ince","erts","erge","icts"]','B',1,'converts — "converts the curved surface ... into a flat image": convert A into B means to change its form. Convince needs a person as its object, converge has no object, and convicts does not fit the meaning.',9),
(@set09_exam_id,'READING','COMPLETE_THE_WORDS','Fill in the missing letters in the paragraph. Word (10): cur_ _ _','Every flat map of the world distorts the planet in some way. A (6) proje_ _ _ _ _ is (7) t_ _ mathematical (8) met_ _ _ that (9) conv_ _ _ _ the (10) cur_ _ _ surface of the globe into a flat image. Some projections preserve the shapes of continents but exaggerate the size of territories near the poles, which is why Greenland can appear as large as Africa. Others maintain accurate areas while bending coastlines. Consequently, navigators, educators, and statisticians select different projections according to their purposes.','NONE','["sed","few","ved","bed"]','C',1,'curved — the surface of a globe is curved, in contrast with the "flat image". Cursed and curbed do not describe a surface, and curfew is a noun.',10),
(@set09_exam_id,'READING','COMPLETE_THE_WORDS','Fill in the missing letters in the paragraph. Word (11): th_ _','Many students assume that typing notes on a laptop is the most efficient way to record a lecture. Research suggests (11) th_ _ this (12) impre_ _ _ _ _ is (13) mist_ _ _ _, since (14) long_ _ _ _ writing (15) do_ _ not permit word-for-word copying. Writers must therefore evaluate which ideas deserve attention, and this additional mental effort strengthens memory. Typists, in contrast, tend to reproduce sentences mechanically, and a week afterward they often recall less.','NONE','["ey","an","em","at"]','D',1,'that — "suggests that" introduces the clause "this impression is mistaken". They, than, and them cannot introduce the clause.',11),
(@set09_exam_id,'READING','COMPLETE_THE_WORDS','Fill in the missing letters in the paragraph. Word (12): impre_ _ _ _ _','Many students assume that typing notes on a laptop is the most efficient way to record a lecture. Research suggests (11) th_ _ this (12) impre_ _ _ _ _ is (13) mist_ _ _ _, since (14) long_ _ _ _ writing (15) do_ _ not permit word-for-word copying. Writers must therefore evaluate which ideas deserve attention, and this additional mental effort strengthens memory. Typists, in contrast, tend to reproduce sentences mechanically, and a week afterward they often recall less.','NONE','["ssion","ssive","ssing","sario"]','A',1,'impression — a singular noun is needed after "this", pointing back to what students assume. Impressive is an adjective, impressing is a verb form, and an impresario is a person who organizes concerts.',12),
(@set09_exam_id,'READING','COMPLETE_THE_WORDS','Fill in the missing letters in the paragraph. Word (13): mist_ _ _ _','Many students assume that typing notes on a laptop is the most efficient way to record a lecture. Research suggests (11) th_ _ this (12) impre_ _ _ _ _ is (13) mist_ _ _ _, since (14) long_ _ _ _ writing (15) do_ _ not permit word-for-word copying. Writers must therefore evaluate which ideas deserve attention, and this additional mental effort strengthens memory. Typists, in contrast, tend to reproduce sentences mechanically, and a week afterward they often recall less.','NONE','["akes","rust","aken","ress"]','C',1,'mistaken — after "is" an adjective meaning wrong is needed: this impression is mistaken. Mistakes, mistrust, and mistress are nouns that do not fit after "this impression is".',13),
(@set09_exam_id,'READING','COMPLETE_THE_WORDS','Fill in the missing letters in the paragraph. Word (14): long_ _ _ _','Many students assume that typing notes on a laptop is the most efficient way to record a lecture. Research suggests (11) th_ _ this (12) impre_ _ _ _ _ is (13) mist_ _ _ _, since (14) long_ _ _ _ writing (15) do_ _ not permit word-for-word copying. Writers must therefore evaluate which ideas deserve attention, and this additional mental effort strengthens memory. Typists, in contrast, tend to reproduce sentences mechanically, and a week afterward they often recall less.','NONE','["hand","horn","boat","bows"]','A',1,'longhand — longhand writing is ordinary writing by hand, which is slower than typing. A longhorn is a cow, and a longboat and longbows are not kinds of writing.',14),
(@set09_exam_id,'READING','COMPLETE_THE_WORDS','Fill in the missing letters in the paragraph. Word (15): do_ _','Many students assume that typing notes on a laptop is the most efficient way to record a lecture. Research suggests (11) th_ _ this (12) impre_ _ _ _ _ is (13) mist_ _ _ _, since (14) long_ _ _ _ writing (15) do_ _ not permit word-for-word copying. Writers must therefore evaluate which ideas deserve attention, and this additional mental effort strengthens memory. Typists, in contrast, tend to reproduce sentences mechanically, and a week afterward they often recall less.','NONE','["ne","or","es","wn"]','C',1,'does — "longhand writing does not permit": the auxiliary for a singular subject before "not". Done, door, and down cannot stand between the subject and "not permit".',15),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read a notice. What is the purpose of the notice?','NOTICE TO RESIDENTS\n\nThe elevator in Building C will be out of service on Thursday, June 12, from 8:00 a.m. to 2:00 p.m. while technicians install a replacement control panel. Please use the stairwells at either end of the corridor. Residents who require assistance carrying groceries or packages may contact the front desk at extension 14.','NONE','["To announce the opening of a new entrance to Building C","To tell residents that a service will be unavailable","To ask residents to stop leaving packages in the corridor","To introduce a new technician at the front desk"]','B',1,'The notice says the elevator will be out of service for six hours on one day, so its purpose is to tell residents that a service will be unavailable for a time.',16),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read a notice. How can residents get help with packages?','NOTICE TO RESIDENTS\n\nThe elevator in Building C will be out of service on Thursday, June 12, from 8:00 a.m. to 2:00 p.m. while technicians install a replacement control panel. Please use the stairwells at either end of the corridor. Residents who require assistance carrying groceries or packages may contact the front desk at extension 14.','NONE','["By asking the technicians for assistance","By using the other elevator","By contacting the front desk","By leaving a note on the control panel"]','C',1,'Residents who require assistance carrying groceries or packages "may contact the front desk at extension 14".',17),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read an email. Why is the final cost lower than expected?','To: Daniel Okafor\nFrom: Hillside Cycle Repair\nSubject: Your bicycle is ready\n\nDear Mr. Okafor,\n\nThe repairs on your bicycle have been completed. We replaced the rear tire and adjusted both brakes. The total comes to $48, which is $12 below our original estimate because the chain turned out to need no replacement. You may collect the bicycle any weekday before 6:00 p.m.; payment is due at pickup. Our workmanship is guaranteed for thirty days.\n\nSincerely,\nMina Park','NONE','["The shop is offering a discount on tires this week.","One part did not have to be replaced.","Mr. Okafor paid in advance.","Only one of the two brakes needed adjusting."]','B',1,'The total is below the estimate "because the chain turned out to need no replacement" — one part did not have to be replaced. Both brakes were adjusted.',18),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read an email. How much did the shop originally expect the repairs to cost?','To: Daniel Okafor\nFrom: Hillside Cycle Repair\nSubject: Your bicycle is ready\n\nDear Mr. Okafor,\n\nThe repairs on your bicycle have been completed. We replaced the rear tire and adjusted both brakes. The total comes to $48, which is $12 below our original estimate because the chain turned out to need no replacement. You may collect the bicycle any weekday before 6:00 p.m.; payment is due at pickup. Our workmanship is guaranteed for thirty days.\n\nSincerely,\nMina Park','NONE','["$36","$48","$60","$72"]','C',1,'The total of $48 is "$12 below our original estimate", so the estimate was $48 + $12 = $60.',19),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read a text chain. Why does Mr. Reyes mention the Chemistry Building?','Priya Nair (9:12 a.m.): Are we still rehearsing the presentation in the library at 11?\nTomas Reyes (9:15 a.m.): Yes, but the group study rooms are closed for carpet cleaning. I reserved the seminar room in the Chemistry Building instead.\nLin Zhao (9:16 a.m.): Is there a projector? I''d rather not carry mine across campus.\nTomas Reyes (9:18 a.m.): No need. The room has one built in, and I tested it yesterday.\nPriya Nair (9:20 a.m.): Great. Should I print the handouts?\nLin Zhao (9:21 a.m.): Hold off. I found two errors in the chart on page 3. I''ll send a corrected file within the hour.\nPriya Nair (9:23 a.m.): Understood. I''ll wait for your version.','NONE','["To explain where he left the projector yesterday","To suggest a place where the handouts can be printed","To describe which rooms are closed for carpet cleaning","To tell the others where the rehearsal will be held"]','D',1,'The library study rooms are closed, so Mr. Reyes "reserved the seminar room in the Chemistry Building instead" — he is telling the others where the rehearsal will be held.',20),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read a text chain. At 9:21 a.m., what does Ms. Zhao imply when she writes, "Hold off"?','Priya Nair (9:12 a.m.): Are we still rehearsing the presentation in the library at 11?\nTomas Reyes (9:15 a.m.): Yes, but the group study rooms are closed for carpet cleaning. I reserved the seminar room in the Chemistry Building instead.\nLin Zhao (9:16 a.m.): Is there a projector? I''d rather not carry mine across campus.\nTomas Reyes (9:18 a.m.): No need. The room has one built in, and I tested it yesterday.\nPriya Nair (9:20 a.m.): Great. Should I print the handouts?\nLin Zhao (9:21 a.m.): Hold off. I found two errors in the chart on page 3. I''ll send a corrected file within the hour.\nPriya Nair (9:23 a.m.): Understood. I''ll wait for your version.','NONE','["The handouts should not be printed yet.","The rehearsal should start later.","She has already printed the corrected handouts.","Priya should remove the chart on page 3 first."]','A',1,'Priya asks whether to print the handouts. Ms. Zhao has found two errors and will send a corrected file, so "Hold off" means the handouts should not be printed yet.',21),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read an advertisement. What will the workshop NOT cover?','GREEN THUMB GARDEN CENTER\nSaturday Workshop: Tomatoes on a Balcony\n\nOur head gardener will demonstrate how to select containers, prepare soil, and water correctly.\nSaturday, April 5, 10:00-11:30 a.m.\nThe $15 fee includes a seedling to take home.\nEnrollment is limited to 12 participants, so register at the counter by Thursday.','NONE','["Selecting containers","Harvesting tomatoes","Preparing soil","Watering plants"]','B',1,'The gardener will demonstrate how to "select containers, prepare soil, and water correctly". Harvesting is not mentioned.',22),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read an advertisement. What must people do in order to attend?','GREEN THUMB GARDEN CENTER\nSaturday Workshop: Tomatoes on a Balcony\n\nOur head gardener will demonstrate how to select containers, prepare soil, and water correctly.\nSaturday, April 5, 10:00-11:30 a.m.\nThe $15 fee includes a seedling to take home.\nEnrollment is limited to 12 participants, so register at the counter by Thursday.','NONE','["Sign up in the store by Thursday","Bring a suitable container from home","Arrive thirty minutes before the class","Pay the head gardener on Saturday"]','A',1,'Because enrollment is limited, people must "register at the counter by Thursday" — sign up in the store by Thursday.',23),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read an email. What is the main purpose of the email?','To: Lena Fischer\nFrom: Riverbend Community Orchestra\nSubject: Welcome to the string section\n\nDear Ms. Fischer,\n\nThank you for auditioning last weekend. We are delighted to offer you a position among our second violins for the coming season.\n\nRehearsals take place every Tuesday from 7:00 to 9:00 p.m. in the auditorium of Westgate Middle School. Under our attendance policy, members who miss more than two rehearsals before a concert relinquish their seat for that performance, so please consult your calendar carefully. Our first concert is on November 22.\n\nPrinted music will be distributed at the first rehearsal on September 9. If you prefer to begin practicing earlier, the parts can be downloaded from the members'' page of our website using the password in the attached letter.\n\nMembership is free of charge; however, each player is expected to volunteer at one fundraising event during the year.\n\nWarm regards,\nPaul Adeyemi\nOrchestra Manager','NONE','["To invite Ms. Fischer to audition for an orchestra","To inform members of a new rehearsal time","To ask Ms. Fischer to donate to a fundraising event","To accept Ms. Fischer as a member of a group"]','D',1,'The audition has already taken place, and the orchestra is "delighted to offer you a position among our second violins" — the email accepts her as a member.',24),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read an email. What is indicated about rehearsals?','To: Lena Fischer\nFrom: Riverbend Community Orchestra\nSubject: Welcome to the string section\n\nDear Ms. Fischer,\n\nThank you for auditioning last weekend. We are delighted to offer you a position among our second violins for the coming season.\n\nRehearsals take place every Tuesday from 7:00 to 9:00 p.m. in the auditorium of Westgate Middle School. Under our attendance policy, members who miss more than two rehearsals before a concert relinquish their seat for that performance, so please consult your calendar carefully. Our first concert is on November 22.\n\nPrinted music will be distributed at the first rehearsal on September 9. If you prefer to begin practicing earlier, the parts can be downloaded from the members'' page of our website using the password in the attached letter.\n\nMembership is free of charge; however, each player is expected to volunteer at one fundraising event during the year.\n\nWarm regards,\nPaul Adeyemi\nOrchestra Manager','NONE','["They take place twice a week in a school auditorium.","They are held in a concert hall that the orchestra owns.","New members must attend an additional session before each concert.","Members who miss too many may lose their place in a concert."]','D',1,'Members who miss more than two rehearsals before a concert "relinquish their seat for that performance"; to relinquish is to give up. Rehearsals are weekly, in a school auditorium.',25),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read an email. What is Ms. Fischer NOT required to do?','To: Lena Fischer\nFrom: Riverbend Community Orchestra\nSubject: Welcome to the string section\n\nDear Ms. Fischer,\n\nThank you for auditioning last weekend. We are delighted to offer you a position among our second violins for the coming season.\n\nRehearsals take place every Tuesday from 7:00 to 9:00 p.m. in the auditorium of Westgate Middle School. Under our attendance policy, members who miss more than two rehearsals before a concert relinquish their seat for that performance, so please consult your calendar carefully. Our first concert is on November 22.\n\nPrinted music will be distributed at the first rehearsal on September 9. If you prefer to begin practicing earlier, the parts can be downloaded from the members'' page of our website using the password in the attached letter.\n\nMembership is free of charge; however, each player is expected to volunteer at one fundraising event during the year.\n\nWarm regards,\nPaul Adeyemi\nOrchestra Manager','NONE','["Help at a fundraising event","Attend rehearsals on Tuesday evenings","Pay a membership fee","Limit her absences before a concert"]','C',1,'"Membership is free of charge", so she does not have to pay a fee. Helping at one fundraising event, Tuesday rehearsals, and the limit on absences are all expected of members.',26),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read a social media post. What is the main purpose of the post?','Jorge Mendes\n\nBig news for the neighborhood: the Elm Street Repair Café opens this Sunday in the former post office! Bring a damaged lamp, a torn jacket, or a toaster that refuses to toast, and one of our volunteer repairers will tackle it alongside you. Nothing is repaired behind a counter here. You sit beside the volunteer and carry out the repair together, so next time you may be able to manage it independently. Our ambition is to keep serviceable belongings out of the landfill.\n\nRepairs are free, although you pay for any replacement parts. Unfortunately, we cannot accept microwave ovens or anything larger than an armchair. Doors open at 1:00 p.m., and items are handled in the order people arrive, so come early. Refreshments are available for purchase, and every cent goes toward equipment.\n\nLike · Comment · Share','NONE','["To announce the opening of a community service","To recruit volunteers who can repair appliances","To advertise used household appliances for sale","To explain why the post office has closed"]','A',1,'The post begins with the news that the Elm Street Repair Café "opens this Sunday" and then explains how it works — it announces the opening of a community service.',27),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read a social media post. According to the post, how is the Repair Café different from an ordinary repair shop?','Jorge Mendes\n\nBig news for the neighborhood: the Elm Street Repair Café opens this Sunday in the former post office! Bring a damaged lamp, a torn jacket, or a toaster that refuses to toast, and one of our volunteer repairers will tackle it alongside you. Nothing is repaired behind a counter here. You sit beside the volunteer and carry out the repair together, so next time you may be able to manage it independently. Our ambition is to keep serviceable belongings out of the landfill.\n\nRepairs are free, although you pay for any replacement parts. Unfortunately, we cannot accept microwave ovens or anything larger than an armchair. Doors open at 1:00 p.m., and items are handled in the order people arrive, so come early. Refreshments are available for purchase, and every cent goes toward equipment.\n\nLike · Comment · Share','NONE','["It repairs large pieces of furniture for free.","It supplies replacement parts at no charge.","Customers must reserve an appointment in advance.","Visitors take part in repairing their own items."]','D',1,'"Nothing is repaired behind a counter here. You sit beside the volunteer and carry out the repair together" — visitors take part. Replacement parts must be paid for, and large items are refused.',28),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read a social media post. The word "serviceable" in the post is closest in meaning to','Jorge Mendes\n\nBig news for the neighborhood: the Elm Street Repair Café opens this Sunday in the former post office! Bring a damaged lamp, a torn jacket, or a toaster that refuses to toast, and one of our volunteer repairers will tackle it alongside you. Nothing is repaired behind a counter here. You sit beside the volunteer and carry out the repair together, so next time you may be able to manage it independently. Our ambition is to keep serviceable belongings out of the landfill.\n\nRepairs are free, although you pay for any replacement parts. Unfortunately, we cannot accept microwave ovens or anything larger than an armchair. Doors open at 1:00 p.m., and items are handled in the order people arrive, so come early. Refreshments are available for purchase, and every cent goes toward equipment.\n\nLike · Comment · Share','NONE','["functional","valuable","fashionable","replaceable"]','A',1,'The café repairs broken things so that belongings that can still be used are not thrown away; "serviceable" means functional, still able to do its job.',29),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read an article. Why is the shuttle route being changed?','CAMPUS NEWS\nNight Shuttle Adds Hospital Stop\n\nBeginning October 1, the university''s night shuttle will stop at the entrance of Mercy Hospital, where more than two hundred nursing students complete their evening clinical placements. Until now, those students have walked fifteen minutes to the nearest stop on College Avenue.\n\nThe additional stop lengthens each circuit by about four minutes, so the shuttle will run every 24 minutes instead of every 20. To compensate for the longer wait, the final departure from the library moves from midnight to 12:30 a.m.\n\nThe change follows a petition signed by 640 students last spring. Transportation director Amy Okoye said the office will evaluate ridership figures in December before determining whether the stop becomes permanent.','NONE','["To shorten the travel time of each circuit","To serve students who train at a hospital","To replace the stop on College Avenue","To reduce the cost of the night service"]','B',1,'The new stop is at Mercy Hospital, "where more than two hundred nursing students complete their evening clinical placements". Each circuit actually becomes longer.',30),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read an article. What will happen to the last shuttle of the night?','CAMPUS NEWS\nNight Shuttle Adds Hospital Stop\n\nBeginning October 1, the university''s night shuttle will stop at the entrance of Mercy Hospital, where more than two hundred nursing students complete their evening clinical placements. Until now, those students have walked fifteen minutes to the nearest stop on College Avenue.\n\nThe additional stop lengthens each circuit by about four minutes, so the shuttle will run every 24 minutes instead of every 20. To compensate for the longer wait, the final departure from the library moves from midnight to 12:30 a.m.\n\nThe change follows a petition signed by 640 students last spring. Transportation director Amy Okoye said the office will evaluate ridership figures in December before determining whether the stop becomes permanent.','NONE','["It will leave the library later than it does now.","It will no longer stop at the hospital entrance.","It will depart from College Avenue at midnight.","It will be suspended until the December review."]','A',1,'"The final departure from the library moves from midnight to 12:30 a.m." — it will leave later than it does now.',31),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read an article. What can be inferred about the hospital stop?','CAMPUS NEWS\nNight Shuttle Adds Hospital Stop\n\nBeginning October 1, the university''s night shuttle will stop at the entrance of Mercy Hospital, where more than two hundred nursing students complete their evening clinical placements. Until now, those students have walked fifteen minutes to the nearest stop on College Avenue.\n\nThe additional stop lengthens each circuit by about four minutes, so the shuttle will run every 24 minutes instead of every 20. To compensate for the longer wait, the final departure from the library moves from midnight to 12:30 a.m.\n\nThe change follows a petition signed by 640 students last spring. Transportation director Amy Okoye said the office will evaluate ridership figures in December before determining whether the stop becomes permanent.','NONE','["It was proposed by Amy Okoye.","It will be used mainly by students in the morning.","It requires nursing students to sign a petition.","It could be removed after a trial period."]','D',1,'The office will evaluate ridership in December "before determining whether the stop becomes permanent", so the stop is on trial and could be removed. It came from a student petition, not from the director.',32),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read a notice. What happens if a plot has not been planted by May 1?','SUNNYSIDE COMMUNITY GARDEN\nPlot Regulations for the New Season\n\n1. Plots are allocated for one year, from March 1 to the end of February. Returning gardeners may retain the same plot provided they renew by February 15.\n2. Each plot must be cultivated by May 1. Gardeners who leave a plot vacant after that date lose their entitlement, and the plot will be reassigned to an applicant on the waiting list.\n3. Water is available from the faucets beside the tool shed. Hoses must be rolled up after use.\n4. Only hand tools may be stored in the shed. Label them with your plot number.\n5. Gardeners are expected to participate in two of the four maintenance days held annually.','NONE','["The gardener must pay a renewal fee.","Volunteers will cultivate it instead.","It may be given to another person.","The gardener must join an extra maintenance day."]','C',1,'Rule 2: gardeners who leave a plot vacant after May 1 "lose their entitlement, and the plot will be reassigned to an applicant on the waiting list".',33),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read a notice. According to the notice, which of the following is NOT permitted?','SUNNYSIDE COMMUNITY GARDEN\nPlot Regulations for the New Season\n\n1. Plots are allocated for one year, from March 1 to the end of February. Returning gardeners may retain the same plot provided they renew by February 15.\n2. Each plot must be cultivated by May 1. Gardeners who leave a plot vacant after that date lose their entitlement, and the plot will be reassigned to an applicant on the waiting list.\n3. Water is available from the faucets beside the tool shed. Hoses must be rolled up after use.\n4. Only hand tools may be stored in the shed. Label them with your plot number.\n5. Gardeners are expected to participate in two of the four maintenance days held annually.','NONE','["Keeping the same plot for a second year","Leaving a hose unrolled after watering","Storing labeled hand tools in the shed","Missing two of the four maintenance days"]','B',1,'Rule 3: "Hoses must be rolled up after use." Returning gardeners may retain a plot (rule 1), hand tools may be stored (rule 4), and only two of the four maintenance days are expected (rule 5).',34),
(@set09_exam_id,'READING','READ_DAILY_LIFE','Read a notice. What can be concluded about the garden?','SUNNYSIDE COMMUNITY GARDEN\nPlot Regulations for the New Season\n\n1. Plots are allocated for one year, from March 1 to the end of February. Returning gardeners may retain the same plot provided they renew by February 15.\n2. Each plot must be cultivated by May 1. Gardeners who leave a plot vacant after that date lose their entitlement, and the plot will be reassigned to an applicant on the waiting list.\n3. Water is available from the faucets beside the tool shed. Hoses must be rolled up after use.\n4. Only hand tools may be stored in the shed. Label them with your plot number.\n5. Gardeners are expected to participate in two of the four maintenance days held annually.','NONE','["New gardeners pay a higher fee than returning ones.","It is closed to gardeners from December to February.","Demand for plots is greater than the supply.","Gardeners must attend every maintenance day."]','C',1,'The garden keeps a waiting list of applicants, so more people want plots than there are plots. No fee is mentioned, and only two of the four maintenance days are expected.',35),
(@set09_exam_id,'READING','READ_PASSAGE','What is the passage mainly about?','Reading Climate in Tree Rings\n\nIn regions with distinct seasons, a tree adds one layer of wood to its trunk annually. Dendrochronology, the scientific discipline that interprets these layers, relies on a simple observation: their thickness reflects growing conditions. Abundant rainfall and moderate temperatures produce a broad ring, whereas drought or prolonged cold leaves a narrow one. Because neighboring trees experience identical weather, they preserve the same sequence of broad and narrow rings.\n\nThis shared signature allows researchers to extend the record far beyond the lifespan of any individual tree. By aligning the outer rings of an ancient beam or buried log with the inner rings of a living specimen, they connect successive samples, a procedure known as cross-dating. In parts of Europe, overlapping samples now constitute a continuous chronology stretching back more than ten thousand years.\n\nSuch chronologies benefit more than climate specialists. Historians have consulted them to establish when the timbers of a ship or a cathedral roof were felled, occasionally to the precise year. The technique nevertheless has limitations. Trees in the humid tropics frequently grow throughout the year without forming recognizable rings, so extensive regions of the world remain sparsely documented.','NONE','["How the yearly growth layers of trees are used to study the past","Why trees in different regions grow at different speeds","How historians restore the timbers of ships and cathedrals","Why tropical forests are difficult for climate specialists to reach"]','A',1,'The passage explains how rings form, how samples are linked by cross-dating, and how the resulting chronologies serve climate research and history — how yearly growth layers are used to study the past.',36),
(@set09_exam_id,'READING','READ_PASSAGE','The word "constitute" in the passage is closest in meaning to','Reading Climate in Tree Rings\n\nIn regions with distinct seasons, a tree adds one layer of wood to its trunk annually. Dendrochronology, the scientific discipline that interprets these layers, relies on a simple observation: their thickness reflects growing conditions. Abundant rainfall and moderate temperatures produce a broad ring, whereas drought or prolonged cold leaves a narrow one. Because neighboring trees experience identical weather, they preserve the same sequence of broad and narrow rings.\n\nThis shared signature allows researchers to extend the record far beyond the lifespan of any individual tree. By aligning the outer rings of an ancient beam or buried log with the inner rings of a living specimen, they connect successive samples, a procedure known as cross-dating. In parts of Europe, overlapping samples now constitute a continuous chronology stretching back more than ten thousand years.\n\nSuch chronologies benefit more than climate specialists. Historians have consulted them to establish when the timbers of a ship or a cathedral roof were felled, occasionally to the precise year. The technique nevertheless has limitations. Trees in the humid tropics frequently grow throughout the year without forming recognizable rings, so extensive regions of the world remain sparsely documented.','NONE','["form","need","replace","measure"]','A',1,'Overlapping samples together make up one continuous chronology, so "constitute" means form.',37),
(@set09_exam_id,'READING','READ_PASSAGE','According to the passage, why do trees growing in the same area show the same pattern of rings?','Reading Climate in Tree Rings\n\nIn regions with distinct seasons, a tree adds one layer of wood to its trunk annually. Dendrochronology, the scientific discipline that interprets these layers, relies on a simple observation: their thickness reflects growing conditions. Abundant rainfall and moderate temperatures produce a broad ring, whereas drought or prolonged cold leaves a narrow one. Because neighboring trees experience identical weather, they preserve the same sequence of broad and narrow rings.\n\nThis shared signature allows researchers to extend the record far beyond the lifespan of any individual tree. By aligning the outer rings of an ancient beam or buried log with the inner rings of a living specimen, they connect successive samples, a procedure known as cross-dating. In parts of Europe, overlapping samples now constitute a continuous chronology stretching back more than ten thousand years.\n\nSuch chronologies benefit more than climate specialists. Historians have consulted them to establish when the timbers of a ship or a cathedral roof were felled, occasionally to the precise year. The technique nevertheless has limitations. Trees in the humid tropics frequently grow throughout the year without forming recognizable rings, so extensive regions of the world remain sparsely documented.','NONE','["They are aligned with ancient beams.","They are exposed to the same weather.","They add layers only in rainy years.","They have the same individual lifespan."]','B',1,'"Because neighboring trees experience identical weather, they preserve the same sequence of broad and narrow rings."',38),
(@set09_exam_id,'READING','READ_PASSAGE','Why does the author mention "the timbers of a ship or a cathedral roof"?','Reading Climate in Tree Rings\n\nIn regions with distinct seasons, a tree adds one layer of wood to its trunk annually. Dendrochronology, the scientific discipline that interprets these layers, relies on a simple observation: their thickness reflects growing conditions. Abundant rainfall and moderate temperatures produce a broad ring, whereas drought or prolonged cold leaves a narrow one. Because neighboring trees experience identical weather, they preserve the same sequence of broad and narrow rings.\n\nThis shared signature allows researchers to extend the record far beyond the lifespan of any individual tree. By aligning the outer rings of an ancient beam or buried log with the inner rings of a living specimen, they connect successive samples, a procedure known as cross-dating. In parts of Europe, overlapping samples now constitute a continuous chronology stretching back more than ten thousand years.\n\nSuch chronologies benefit more than climate specialists. Historians have consulted them to establish when the timbers of a ship or a cathedral roof were felled, occasionally to the precise year. The technique nevertheless has limitations. Trees in the humid tropics frequently grow throughout the year without forming recognizable rings, so extensive regions of the world remain sparsely documented.','NONE','["To show that ancient timber is stronger than modern timber","To explain why wood from old buildings is frequently reused","To argue that historians depend too heavily on climate science","To give examples of objects that tree rings can help to date"]','D',1,'Historians consult the chronologies "to establish when the timbers of a ship or a cathedral roof were felled" — these are examples of objects that tree rings can help to date.',39),
(@set09_exam_id,'READING','READ_PASSAGE','What can be inferred about the humid tropics?','Reading Climate in Tree Rings\n\nIn regions with distinct seasons, a tree adds one layer of wood to its trunk annually. Dendrochronology, the scientific discipline that interprets these layers, relies on a simple observation: their thickness reflects growing conditions. Abundant rainfall and moderate temperatures produce a broad ring, whereas drought or prolonged cold leaves a narrow one. Because neighboring trees experience identical weather, they preserve the same sequence of broad and narrow rings.\n\nThis shared signature allows researchers to extend the record far beyond the lifespan of any individual tree. By aligning the outer rings of an ancient beam or buried log with the inner rings of a living specimen, they connect successive samples, a procedure known as cross-dating. In parts of Europe, overlapping samples now constitute a continuous chronology stretching back more than ten thousand years.\n\nSuch chronologies benefit more than climate specialists. Historians have consulted them to establish when the timbers of a ship or a cathedral roof were felled, occasionally to the precise year. The technique nevertheless has limitations. Trees in the humid tropics frequently grow throughout the year without forming recognizable rings, so extensive regions of the world remain sparsely documented.','NONE','["Trees there live longer than trees in Europe.","Continuous chronologies have been completed there.","Timber from there is rarely used for building.","Ring-based dating is difficult to carry out there."]','D',1,'Tropical trees often grow all year "without forming recognizable rings, so extensive regions of the world remain sparsely documented"; without clear rings, ring-based dating is difficult there.',40),
(@set09_exam_id,'READING','READ_PASSAGE','According to the first paragraph, how did towns set their clocks until the mid-nineteenth century?','How Railways Standardized Time\n\nUntil the mid-nineteenth century, every town observed its own local time, a system in which clocks were regulated by the position of the sun above that particular community. Consequently, a town some twenty or thirty kilometers to the east ran a minute or two ahead of its western neighbor. For travelers on foot or horseback, such discrepancies were negligible.\n\nRailways transformed this harmless variety into a hazard. A train could traverse several local times in a single afternoon, and a timetable printed in one city meant little in the next. (A) Passengers missed connections, and on shared tracks confusion over minutes created a genuine risk of collisions. (B) During the 1840s, British railway companies responded by operating all their trains according to London time. (C) By the mid-1850s, most British towns had adjusted their public clocks to match the station. (D)\n\nNorth America, considerably wider, required a different remedy. In 1883 its railroads divided the continent into broad zones, each differing from the next by one hour, and the following year an international conference designated Greenwich as the world''s prime meridian, the reference line from which longitude is measured. Governments were slow to legislate, but ordinary people had already adopted the zones, since the trains would not wait.','NONE','["By observing the position of the sun","By following the clocks of the nearest large city","By consulting the timetable of the local station","By agreeing on a time with neighboring towns"]','A',1,'Under local time, "clocks were regulated by the position of the sun above that particular community".',41),
(@set09_exam_id,'READING','READ_PASSAGE','The word "negligible" in the passage is closest in meaning to','How Railways Standardized Time\n\nUntil the mid-nineteenth century, every town observed its own local time, a system in which clocks were regulated by the position of the sun above that particular community. Consequently, a town some twenty or thirty kilometers to the east ran a minute or two ahead of its western neighbor. For travelers on foot or horseback, such discrepancies were negligible.\n\nRailways transformed this harmless variety into a hazard. A train could traverse several local times in a single afternoon, and a timetable printed in one city meant little in the next. (A) Passengers missed connections, and on shared tracks confusion over minutes created a genuine risk of collisions. (B) During the 1840s, British railway companies responded by operating all their trains according to London time. (C) By the mid-1850s, most British towns had adjusted their public clocks to match the station. (D)\n\nNorth America, considerably wider, required a different remedy. In 1883 its railroads divided the continent into broad zones, each differing from the next by one hour, and the following year an international conference designated Greenwich as the world''s prime meridian, the reference line from which longitude is measured. Governments were slow to legislate, but ordinary people had already adopted the zones, since the trains would not wait.','NONE','["temporary","insignificant","hazardous","predictable"]','B',1,'For slow travelers a difference of a minute or two did not matter, so the discrepancies were negligible, that is, insignificant.',42),
(@set09_exam_id,'READING','READ_PASSAGE','Why does the author mention collisions?','How Railways Standardized Time\n\nUntil the mid-nineteenth century, every town observed its own local time, a system in which clocks were regulated by the position of the sun above that particular community. Consequently, a town some twenty or thirty kilometers to the east ran a minute or two ahead of its western neighbor. For travelers on foot or horseback, such discrepancies were negligible.\n\nRailways transformed this harmless variety into a hazard. A train could traverse several local times in a single afternoon, and a timetable printed in one city meant little in the next. (A) Passengers missed connections, and on shared tracks confusion over minutes created a genuine risk of collisions. (B) During the 1840s, British railway companies responded by operating all their trains according to London time. (C) By the mid-1850s, most British towns had adjusted their public clocks to match the station. (D)\n\nNorth America, considerably wider, required a different remedy. In 1883 its railroads divided the continent into broad zones, each differing from the next by one hour, and the following year an international conference designated Greenwich as the world''s prime meridian, the reference line from which longitude is measured. Governments were slow to legislate, but ordinary people had already adopted the zones, since the trains would not wait.','NONE','["To explain why early trains traveled slowly on shared tracks","To criticize the British railway companies for poor timetables","To show that differences in local time could be dangerous","To suggest that passengers preferred to travel on horseback"]','C',1,'The risk of collisions is the most serious result of "confusion over minutes"; it shows that differences in local time could be dangerous.',43),
(@set09_exam_id,'READING','READ_PASSAGE','Four locations in the second paragraph are marked (A), (B), (C), and (D). The following sentence could be added at one of them. "These dangers made it clear that a single time was needed along each line." Where does the sentence fit best?','How Railways Standardized Time\n\nUntil the mid-nineteenth century, every town observed its own local time, a system in which clocks were regulated by the position of the sun above that particular community. Consequently, a town some twenty or thirty kilometers to the east ran a minute or two ahead of its western neighbor. For travelers on foot or horseback, such discrepancies were negligible.\n\nRailways transformed this harmless variety into a hazard. A train could traverse several local times in a single afternoon, and a timetable printed in one city meant little in the next. (A) Passengers missed connections, and on shared tracks confusion over minutes created a genuine risk of collisions. (B) During the 1840s, British railway companies responded by operating all their trains according to London time. (C) By the mid-1850s, most British towns had adjusted their public clocks to match the station. (D)\n\nNorth America, considerably wider, required a different remedy. In 1883 its railroads divided the continent into broad zones, each differing from the next by one hour, and the following year an international conference designated Greenwich as the world''s prime meridian, the reference line from which longitude is measured. Governments were slow to legislate, but ordinary people had already adopted the zones, since the trains would not wait.','NONE','["Option A","Option B","Option C","Option D"]','B',1,'"These dangers" points back to the missed connections and the risk of collisions in the sentence before (B), and the sentence leads into what the railway companies then did (operating all trains on London time). Option B.',44),
(@set09_exam_id,'READING','READ_PASSAGE','What does the author suggest about time zones in North America?','How Railways Standardized Time\n\nUntil the mid-nineteenth century, every town observed its own local time, a system in which clocks were regulated by the position of the sun above that particular community. Consequently, a town some twenty or thirty kilometers to the east ran a minute or two ahead of its western neighbor. For travelers on foot or horseback, such discrepancies were negligible.\n\nRailways transformed this harmless variety into a hazard. A train could traverse several local times in a single afternoon, and a timetable printed in one city meant little in the next. (A) Passengers missed connections, and on shared tracks confusion over minutes created a genuine risk of collisions. (B) During the 1840s, British railway companies responded by operating all their trains according to London time. (C) By the mid-1850s, most British towns had adjusted their public clocks to match the station. (D)\n\nNorth America, considerably wider, required a different remedy. In 1883 its railroads divided the continent into broad zones, each differing from the next by one hour, and the following year an international conference designated Greenwich as the world''s prime meridian, the reference line from which longitude is measured. Governments were slow to legislate, but ordinary people had already adopted the zones, since the trains would not wait.','NONE','["They were created by an international conference.","Governments forced the railroads to adopt them.","People were using them before the law required it.","They were designed to match the zones used in Britain."]','C',1,'"Governments were slow to legislate, but ordinary people had already adopted the zones" — people were using them before the law required it. The railroads, not the conference, created the zones.',45),
(@set09_exam_id,'READING','READ_PASSAGE','According to the passage, what does the fungus contribute to a lichen?','Lichens, Pioneers on Bare Rock\n\nWhen a glacier retreats or lava solidifies, it exposes rock without any soil, and few organisms can colonize such a surface. Among the earliest arrivals are lichens. A lichen is not a single organism but a symbiosis, a close partnership between different species: a fungus provides a protective structure that retains moisture, while microscopic algae living inside it manufacture nutrients from sunlight. Together they tolerate conditions that neither could survive alone.\n\nLichens gradually alter the rock beneath them. They secrete weak acids that dissolve its surface, and their bodies expand and contract as they absorb water and dry out, loosening tiny fragments. When lichens die, their remains combine with these fragments and with dust deposited by the wind. Over decades, the result is a thin layer of primitive soil.\n\nThat layer is sufficient for mosses, and subsequently for grasses and small shrubs, whose roots fracture the rock further. Ironically, the newcomers eventually shade out the lichens that made their establishment possible. Ecologists call this sequence primary succession, the development of a community where none existed before. It rarely proceeds quickly: in polar regions, rock exposed for centuries may still support little except lichens.','NONE','["It manufactures nutrients from sunlight.","It shades the mosses that arrive later.","It collects dust deposited by the wind.","It forms a structure that keeps water in."]','D',1,'"A fungus provides a protective structure that retains moisture" — it forms a structure that keeps water in. The algae make the nutrients.',46),
(@set09_exam_id,'READING','READ_PASSAGE','Which of the following is NOT mentioned as a way in which lichens help to create soil?','Lichens, Pioneers on Bare Rock\n\nWhen a glacier retreats or lava solidifies, it exposes rock without any soil, and few organisms can colonize such a surface. Among the earliest arrivals are lichens. A lichen is not a single organism but a symbiosis, a close partnership between different species: a fungus provides a protective structure that retains moisture, while microscopic algae living inside it manufacture nutrients from sunlight. Together they tolerate conditions that neither could survive alone.\n\nLichens gradually alter the rock beneath them. They secrete weak acids that dissolve its surface, and their bodies expand and contract as they absorb water and dry out, loosening tiny fragments. When lichens die, their remains combine with these fragments and with dust deposited by the wind. Over decades, the result is a thin layer of primitive soil.\n\nThat layer is sufficient for mosses, and subsequently for grasses and small shrubs, whose roots fracture the rock further. Ironically, the newcomers eventually shade out the lichens that made their establishment possible. Ecologists call this sequence primary succession, the development of a community where none existed before. It rarely proceeds quickly: in polar regions, rock exposed for centuries may still support little except lichens.','NONE','["Secreting acids that dissolve rock","Bringing dust from other places","Loosening small fragments of rock","Adding their remains after they die"]','B',1,'Acids, loosened fragments, and dead remains are all the work of lichens, but the dust is "deposited by the wind", not brought by lichens.',47),
(@set09_exam_id,'READING','READ_PASSAGE','The word "secrete" in the passage is closest in meaning to','Lichens, Pioneers on Bare Rock\n\nWhen a glacier retreats or lava solidifies, it exposes rock without any soil, and few organisms can colonize such a surface. Among the earliest arrivals are lichens. A lichen is not a single organism but a symbiosis, a close partnership between different species: a fungus provides a protective structure that retains moisture, while microscopic algae living inside it manufacture nutrients from sunlight. Together they tolerate conditions that neither could survive alone.\n\nLichens gradually alter the rock beneath them. They secrete weak acids that dissolve its surface, and their bodies expand and contract as they absorb water and dry out, loosening tiny fragments. When lichens die, their remains combine with these fragments and with dust deposited by the wind. Over decades, the result is a thin layer of primitive soil.\n\nThat layer is sufficient for mosses, and subsequently for grasses and small shrubs, whose roots fracture the rock further. Ironically, the newcomers eventually shade out the lichens that made their establishment possible. Ecologists call this sequence primary succession, the development of a community where none existed before. It rarely proceeds quickly: in polar regions, rock exposed for centuries may still support little except lichens.','NONE','["absorb","resist","contain","release"]','D',1,'Lichens produce weak acids and let them out onto the rock, where the acids dissolve its surface; "secrete" means release.',48),
(@set09_exam_id,'READING','READ_PASSAGE','Why does the author mention polar regions?','Lichens, Pioneers on Bare Rock\n\nWhen a glacier retreats or lava solidifies, it exposes rock without any soil, and few organisms can colonize such a surface. Among the earliest arrivals are lichens. A lichen is not a single organism but a symbiosis, a close partnership between different species: a fungus provides a protective structure that retains moisture, while microscopic algae living inside it manufacture nutrients from sunlight. Together they tolerate conditions that neither could survive alone.\n\nLichens gradually alter the rock beneath them. They secrete weak acids that dissolve its surface, and their bodies expand and contract as they absorb water and dry out, loosening tiny fragments. When lichens die, their remains combine with these fragments and with dust deposited by the wind. Over decades, the result is a thin layer of primitive soil.\n\nThat layer is sufficient for mosses, and subsequently for grasses and small shrubs, whose roots fracture the rock further. Ironically, the newcomers eventually shade out the lichens that made their establishment possible. Ecologists call this sequence primary succession, the development of a community where none existed before. It rarely proceeds quickly: in polar regions, rock exposed for centuries may still support little except lichens.','NONE','["To show that primary succession can be extremely slow","To identify the place where lichens first appeared","To explain why glaciers in those regions are retreating","To argue that lichens cannot tolerate severe cold"]','A',1,'The example follows "It rarely proceeds quickly": rock exposed for centuries may still have little except lichens, which shows how slow primary succession can be.',49),
(@set09_exam_id,'READING','READ_PASSAGE','What can be inferred about lichens once grasses and shrubs have become established?','Lichens, Pioneers on Bare Rock\n\nWhen a glacier retreats or lava solidifies, it exposes rock without any soil, and few organisms can colonize such a surface. Among the earliest arrivals are lichens. A lichen is not a single organism but a symbiosis, a close partnership between different species: a fungus provides a protective structure that retains moisture, while microscopic algae living inside it manufacture nutrients from sunlight. Together they tolerate conditions that neither could survive alone.\n\nLichens gradually alter the rock beneath them. They secrete weak acids that dissolve its surface, and their bodies expand and contract as they absorb water and dry out, loosening tiny fragments. When lichens die, their remains combine with these fragments and with dust deposited by the wind. Over decades, the result is a thin layer of primitive soil.\n\nThat layer is sufficient for mosses, and subsequently for grasses and small shrubs, whose roots fracture the rock further. Ironically, the newcomers eventually shade out the lichens that made their establishment possible. Ecologists call this sequence primary succession, the development of a community where none existed before. It rarely proceeds quickly: in polar regions, rock exposed for centuries may still support little except lichens.','NONE','["They grow faster in the newly formed soil.","They spread onto the roots of the new plants.","They no longer receive enough light to thrive.","They begin to dissolve the primitive soil layer."]','C',1,'The newcomers "eventually shade out the lichens"; to shade out is to block the light, so the lichens no longer receive enough light to thrive.',50);
INSERT INTO tp_questions (exam_id, section, task_type, prompt, body_text, audio_mode, choices_json, answer_key, auto_score, explanation, order_no) VALUES
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','Where should I leave the signed forms?','TTS','["By Friday afternoon at the very latest.","Yes, I signed all three of them.","In the tray by the front desk.","It left about an hour ago."]','C',1,'A where-question asks for a place; "In the tray by the front desk" gives one.',51),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','Didn''t the pharmacy use to be on this corner?','TTS','["It moved across the street.","Yes, I used it again this morning.","Turn left at the next corner.","A prescription is required for those."]','A',1,'The speaker is checking a memory about where the pharmacy was; "It moved across the street" confirms it and explains the change.',52),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','How long has the copier been broken?','TTS','["About ten pages long, I think.","Two copies of each, please.","The technician is very tall.","Since Monday, I believe."]','D',1,'"How long has ... been" asks about a period of time; "Since Monday" answers it.',53),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','I can''t get the projector to turn on.','TTS','["The project is due next week.","Yes, turn right at the stairs.","It was on the news.","Have you checked the power cable?"]','D',1,'The speaker reports a problem with a machine; the helpful reply, "Have you checked the power cable?", suggests a cause to check. The other options only repeat sounds such as "project", "turn", and "on".',54),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','Would you rather meet before lunch or after?','TTS','["Yes, I would.","A sandwich and some soup, please.","Either works for me.","We met last year."]','C',1,'A choice question cannot be answered with yes; "Either works for me" responds to both options.',55),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','Who''s picking up the client from the airport?','TTS','["At terminal two.","I thought you were.","Her flight was delayed twice.","He picked the blue one."]','B',1,'A who-question asks for a person; "I thought you were" (picking up the client) names one.',56),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','Could you keep an eye on my bag for a minute?','TTS','["No, that one isn''t mine.","I bought it on sale last week.","A minute ago.","Sure, take your time."]','D',1,'The speaker makes a request; "Sure, take your time" agrees to it.',57),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','The seminar has been moved to room three ten, hasn''t it?','TTS','["No, I haven''t moved there yet.","It lasts about three hours.","That''s what the email said.","Thirty people have signed up."]','C',1,'A tag question asks for confirmation; "That''s what the email said" confirms the room change.',58),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','Why is the parking lot so empty today?','TTS','["By the main gate.","It''s a public holiday.","I parked there yesterday morning.","Because it''s completely full."]','B',1,'A why-question asks for a reason; a public holiday explains an empty parking lot. "Because it''s completely full" contradicts the question.',59),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','When do you expect the shipment to arrive?','TTS','["From the warehouse in Denver, I think.","By truck, most likely.","Yes, I expected that.","Not until the end of the week."]','D',1,'A when-question asks for a time; "Not until the end of the week" gives one.',60),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','That was the best lecture we''ve had all term.','TTS','["I agree. The hour flew by.","It''s on the third floor, I think.","I''ll have the same, thanks.","No, the term ends in June."]','A',1,'The speaker gives an opinion; the natural reply agrees or disagrees with it. "I agree. The hour flew by" does so.',61),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','Do you know if the cafeteria takes credit cards?','TTS','["Yes, I''ve known him for many years.","I''ve only ever paid cash there.","The soup is usually good.","I''ll take two, thanks."]','B',1,'The speaker wants to know about payment; "I''ve only ever paid cash there" answers indirectly that the responder is not sure cards are accepted.',62),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','How did your presentation go?','TTS','["By bus, for the most part.","At ten o''clock.","To the marketing team.","Better than I had expected."]','D',1,'"How did it go?" asks how successful something was; "Better than I had expected" evaluates it.',63),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','Should we order more chairs for the event?','TTS','["Let''s see how many sign up first.","They were delivered in alphabetical order.","Yes, the chairman will speak.","It was a great event."]','A',1,'The speaker asks for a decision; "Let''s see how many sign up first" proposes waiting before deciding.',64),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','Whose turn is it to lead the study group?','TTS','["Turn left just after the library.","We study in room four.","Mine, unless Maria wants to swap.","It leads to the gym."]','C',1,'A whose-question asks which person; "Mine" says that it is the responder''s own turn.',65),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','I''m thinking of signing up for the Saturday baking course.','TTS','["Oh, when does it start?","No, I didn''t sign it yesterday.","The bakery closes at six.","I thought so too."]','A',1,'The speaker shares a plan; showing interest with a follow-up question, "Oh, when does it start?", is the natural reply.',66),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','Have you had a chance to look over my draft?','TTS','["Yes, that window is quite drafty.","It''s a chance worth taking.","I''m about halfway through it.","No, I overlooked the parking sign."]','C',1,'The speaker asks whether the draft has been read; "I''m about halfway through it" reports the progress.',67),
(@set09_exam_id,'LISTENING','LISTEN_RESPONSE','Choose the best response.','What''s the quickest way to get downtown from here?','TTS','["About twenty minutes ago, I think.","Probably the express bus.","Downtown is very crowded.","I''m in no hurry."]','B',1,'The question asks for a means of travel; "Probably the express bus" names one.',68),
(@set09_exam_id,'LISTENING','LISTEN_CONVERSATION','Listen to a conversation. What problem are the speakers discussing?','Woman: Hey, did you remember to call the landlord about the kitchen sink? — Man: I did, this morning. He said a plumber is available on Thursday, but somebody has to be home between nine and noon. — Woman: Thursday? My driving test is scheduled for ten. — Man: I can work from home that day. My team meeting is online anyway. — Woman: Perfect. I''ll make dinner that evening to say thanks.','TTS','["A repair that is needed in their home","A driving test that was missed","A rent payment that is overdue","A team meeting that was canceled online"]','A',1,'They talk about calling the landlord about the kitchen sink and a plumber''s visit — a repair needed in their home.',69),
(@set09_exam_id,'LISTENING','LISTEN_CONVERSATION','Listen to a conversation. Why does the man mention his team meeting?','Woman: Hey, did you remember to call the landlord about the kitchen sink? — Man: I did, this morning. He said a plumber is available on Thursday, but somebody has to be home between nine and noon. — Woman: Thursday? My driving test is scheduled for ten. — Man: I can work from home that day. My team meeting is online anyway. — Woman: Perfect. I''ll make dinner that evening to say thanks.','TTS','["To show that he is able to stay home on Thursday","To explain why he cannot be home on Thursday morning","To ask the woman to change the date of her test","To suggest that the plumber come on another day"]','A',1,'He says he can work from home because his meeting "is online anyway" — the meeting does not stop him from staying home on Thursday.',70),
(@set09_exam_id,'LISTENING','LISTEN_CONVERSATION','Listen to a conversation. What is the man trying to arrange?','Man: I''m trying to book a table for Saturday, but that Italian place on Grove Street has nothing available until nine thirty. — Woman: That''s late for your parents, isn''t it? They''ll have been driving for six hours. — Man: Exactly. I could try the restaurant at the top of the harbor tower instead. — Woman: Isn''t the elevator there still being repaired? Your mother couldn''t manage all those stairs. — Man: Good point. Then I''ll reserve the Italian place for Sunday lunch, and we''ll just order something in on Saturday.','TTS','["A sightseeing trip to the harbor tower","A repair to a restaurant elevator","A dinner for visiting family members","A six-hour drive to see his parents"]','C',1,'He is trying to book a table for Saturday, when his parents arrive after a long drive — a dinner for visiting family members.',71),
(@set09_exam_id,'LISTENING','LISTEN_CONVERSATION','Listen to a conversation. What will the man most likely do on Saturday?','Man: I''m trying to book a table for Saturday, but that Italian place on Grove Street has nothing available until nine thirty. — Woman: That''s late for your parents, isn''t it? They''ll have been driving for six hours. — Man: Exactly. I could try the restaurant at the top of the harbor tower instead. — Woman: Isn''t the elevator there still being repaired? Your mother couldn''t manage all those stairs. — Man: Good point. Then I''ll reserve the Italian place for Sunday lunch, and we''ll just order something in on Saturday.','TTS','["Eat at the Italian restaurant at nine thirty","Take his parents to the harbor tower","Have food delivered to his home","Ask his parents to arrive on Sunday"]','C',1,'The Italian place is too late and his mother could not climb the stairs at the tower, so he decides, "we''ll just order something in on Saturday" — he will have food delivered.',72),
(@set09_exam_id,'LISTENING','LISTEN_CONVERSATION','Listen to a conversation. Why did the woman return to the store?','Woman: Hi, I purchased this jacket here last week, but the zipper keeps getting stuck. — Man: I''m sorry about that. Do you have the receipt? — Woman: I paid by card, so I only have the email confirmation on my phone. — Man: That''s fine. Unfortunately, we don''t have any more in that size. I can give you a refund, or I can order a replacement from our other branch, which would probably take about five days. — Woman: I leave for a hiking trip the day after tomorrow, so I''d better take the refund.','TTS','["The jacket she bought was the wrong size.","The item she bought does not work properly.","She was charged twice for the same jacket.","She lost the receipt for her purchase."]','B',1,'She says the jacket''s "zipper keeps getting stuck" — the item does not work properly.',73),
(@set09_exam_id,'LISTENING','LISTEN_CONVERSATION','Listen to a conversation. Why does the woman choose a refund?','Woman: Hi, I purchased this jacket here last week, but the zipper keeps getting stuck. — Man: I''m sorry about that. Do you have the receipt? — Woman: I paid by card, so I only have the email confirmation on my phone. — Man: That''s fine. Unfortunately, we don''t have any more in that size. I can give you a refund, or I can order a replacement from our other branch, which would probably take about five days. — Woman: I leave for a hiking trip the day after tomorrow, so I''d better take the refund.','TTS','["She found a cheaper jacket at another branch.","She does not trust the email confirmation.","She paid in cash and wants cash back.","A replacement would not arrive in time."]','D',1,'A replacement would take about five days, but she leaves for a hiking trip the day after tomorrow, so it would not arrive in time.',74),
(@set09_exam_id,'LISTENING','LISTEN_CONVERSATION','Listen to a conversation. What is the man''s concern about his schedule?','Man: Have you seen the schedule for next month? They''ve put me on the early shift three weeks in a row. — Woman: I thought you preferred mornings. — Man: I do, but my evening class starts at six, and after getting up at four thirty I can barely concentrate by then. — Woman: Why not ask Dana to exchange a week with you? She mentioned she''d rather finish early so she can pick up her children. — Man: Really? I''ll talk to her at lunch.','TTS','["He will be too tired for his class.","His shifts overlap with his evening class.","He dislikes working in the morning.","He was not given enough hours next month."]','A',1,'He likes mornings, but after getting up at four thirty he "can barely concentrate" by the time his six o''clock class starts — he will be too tired for it.',75),
(@set09_exam_id,'LISTENING','LISTEN_CONVERSATION','Listen to a conversation. What does the woman imply about Dana?','Man: Have you seen the schedule for next month? They''ve put me on the early shift three weeks in a row. — Woman: I thought you preferred mornings. — Man: I do, but my evening class starts at six, and after getting up at four thirty I can barely concentrate by then. — Woman: Why not ask Dana to exchange a week with you? She mentioned she''d rather finish early so she can pick up her children. — Man: Really? I''ll talk to her at lunch.','TTS','["She is responsible for making the monthly schedule.","She would probably be glad to work the early shift.","She takes the same evening class as the man does.","She has already agreed to exchange shifts with him."]','B',1,'Dana "would rather finish early so she can pick up her children", so she would probably be glad to take the early shift. She has not been asked yet.',76),
(@set09_exam_id,'LISTENING','LISTEN_CONVERSATION','Listen to a conversation. What caused the problem with the woman''s reservation?','Woman: Excuse me, I reserved a study room for two o''clock, but there are people in it. — Man: Let me check. Room four, under Garcia? — Woman: That''s right. — Man: I see what happened. The previous group extended their booking online, and the system didn''t catch the overlap. Room seven is available right now. It''s smaller, but it has a whiteboard and a bigger screen. — Woman: There are only three of us, and we need to practice our slides, so that''s actually better.','TTS','["The woman arrived late for her booking.","The woman reserved the room for the wrong day.","The room was closed for repairs.","Two bookings overlapped by mistake."]','D',1,'The previous group extended its booking and "the system didn''t catch the overlap" — two bookings overlapped by mistake.',77),
(@set09_exam_id,'LISTENING','LISTEN_CONVERSATION','Listen to a conversation. Why is the woman satisfied with the room she is offered?','Woman: Excuse me, I reserved a study room for two o''clock, but there are people in it. — Man: Let me check. Room four, under Garcia? — Woman: That''s right. — Man: I see what happened. The previous group extended their booking online, and the system didn''t catch the overlap. Room seven is available right now. It''s smaller, but it has a whiteboard and a bigger screen. — Woman: There are only three of us, and we need to practice our slides, so that''s actually better.','TTS','["It is closer to the library entrance.","It suits what her group plans to do.","It is larger than the room she reserved.","It is available for a longer time."]','B',1,'Her group is small and needs to practice slides, and room seven has a bigger screen, so it suits what the group plans to do. The room is smaller, not larger.',78),
(@set09_exam_id,'LISTENING','LISTEN_CONVERSATION','Listen to a conversation. Why did the woman leave the fair early?','Man: You''re back early. I thought the pottery fair continued until five. — Woman: It does, but I''d spent my entire budget by noon, so I figured I''d better leave. — Man: What did you get? — Woman: Two bowls and a teapot from that potter I mentioned, the one who mixes ash into her glazes. — Man: The one with the two-year waiting list? — Woman: That''s the one. She normally sells only by mail order, but she brings a few pieces to this fair every spring. That''s exactly why I arrived the minute it opened.','TTS','["The fair closed earlier than expected.","The potter she likes had sold everything.","The man asked her to come home by noon.","She had no money left to spend."]','D',1,'She says, "I''d spent my entire budget by noon" — she had no money left to spend.',79),
(@set09_exam_id,'LISTENING','LISTEN_CONVERSATION','Listen to a conversation. What does the woman imply about the potter''s work?','Man: You''re back early. I thought the pottery fair continued until five. — Woman: It does, but I''d spent my entire budget by noon, so I figured I''d better leave. — Man: What did you get? — Woman: Two bowls and a teapot from that potter I mentioned, the one who mixes ash into her glazes. — Man: The one with the two-year waiting list? — Woman: That''s the one. She normally sells only by mail order, but she brings a few pieces to this fair every spring. That''s exactly why I arrived the minute it opened.','TTS','["It is sold mostly at spring fairs.","It costs less at fairs than by mail.","It is not easy to obtain.","It is made only in the spring."]','C',1,'There is a two-year waiting list, the potter normally sells only by mail order, and only a few pieces come to the fair, which is why the woman arrived the minute it opened — the work is not easy to obtain.',80),
(@set09_exam_id,'LISTENING','LISTEN_ANNOUNCEMENT','Listen to an announcement in a classroom. What is the main purpose of the announcement?','Before we begin, a quick reminder about next week''s field trip to the water treatment plant. The bus departs from the north parking lot at eight fifteen sharp, not from the science building as the syllabus says. Wear closed-toe shoes, because we''ll be walking on metal platforms. Photography isn''t permitted inside, so you can leave your cameras at home. And please bring the signed safety form. Without it, I''m afraid you''ll have to remain on the bus.','TTS','["To cancel a field trip to a treatment plant","To give instructions for an upcoming visit","To explain how a water treatment plant works","To assign a group project on water safety"]','B',1,'The speaker tells students where the bus leaves, what to wear, and what to bring for next week''s field trip — instructions for an upcoming visit.',81),
(@set09_exam_id,'LISTENING','LISTEN_ANNOUNCEMENT','Listen to an announcement in a classroom. What information on the syllabus does the speaker correct?','Before we begin, a quick reminder about next week''s field trip to the water treatment plant. The bus departs from the north parking lot at eight fifteen sharp, not from the science building as the syllabus says. Wear closed-toe shoes, because we''ll be walking on metal platforms. Photography isn''t permitted inside, so you can leave your cameras at home. And please bring the signed safety form. Without it, I''m afraid you''ll have to remain on the bus.','TTS','["The time the bus leaves the campus","The date of the field trip","The destination of the trip","The place the bus leaves from"]','D',1,'The bus departs from the north parking lot, "not from the science building as the syllabus says" — the speaker corrects the place the bus leaves from.',82),
(@set09_exam_id,'LISTENING','LISTEN_ANNOUNCEMENT','Listen to an announcement in a classroom. What will happen to students who do not bring the form?','Before we begin, a quick reminder about next week''s field trip to the water treatment plant. The bus departs from the north parking lot at eight fifteen sharp, not from the science building as the syllabus says. Wear closed-toe shoes, because we''ll be walking on metal platforms. Photography isn''t permitted inside, so you can leave your cameras at home. And please bring the signed safety form. Without it, I''m afraid you''ll have to remain on the bus.','TTS','["They will not be able to go inside the plant.","They will have to pay a fee to the driver.","They will be sent back to the science building.","They will be asked to take photographs instead."]','A',1,'Without the signed safety form, "you''ll have to remain on the bus" — those students will not be able to go inside the plant.',83),
(@set09_exam_id,'LISTENING','LISTEN_ANNOUNCEMENT','Listen to an announcement on a campus radio station. What is the announcement mainly about?','Good afternoon. This is campus radio with an update from the student recreation center. The winter schedule begins on Monday, and there are a few changes. The swimming pool will open at six instead of seven on weekday mornings, in response to numerous requests for an earlier start. The Wednesday yoga class is relocating from the gymnasium to the dance studio upstairs, which stays warmer in winter. Finally, the front desk will no longer handle cash, so please pay for classes by card or through the university app.','TTS','["The hiring of a new yoga instructor","The closing of the swimming pool in winter","Changes to the services at a facility","A discount on classes paid for by card"]','C',1,'The speaker lists three changes in the winter schedule of the recreation center: pool hours, the yoga room, and payment — changes to the services at a facility.',84),
(@set09_exam_id,'LISTENING','LISTEN_ANNOUNCEMENT','Listen to an announcement on a campus radio station. Why will the pool open earlier?','Good afternoon. This is campus radio with an update from the student recreation center. The winter schedule begins on Monday, and there are a few changes. The swimming pool will open at six instead of seven on weekday mornings, in response to numerous requests for an earlier start. The Wednesday yoga class is relocating from the gymnasium to the dance studio upstairs, which stays warmer in winter. Finally, the front desk will no longer handle cash, so please pay for classes by card or through the university app.','TTS','["Users asked for the change.","The pool will close earlier in the evening.","The swim team needs more practice time.","Heating costs are lower in the morning."]','A',1,'The pool opens at six "in response to numerous requests for an earlier start" — the people who use the pool asked for the change.',85),
(@set09_exam_id,'LISTENING','LISTEN_ANNOUNCEMENT','Listen to an announcement on a campus radio station. What are listeners told about paying for classes?','Good afternoon. This is campus radio with an update from the student recreation center. The winter schedule begins on Monday, and there are a few changes. The swimming pool will open at six instead of seven on weekday mornings, in response to numerous requests for an earlier start. The Wednesday yoga class is relocating from the gymnasium to the dance studio upstairs, which stays warmer in winter. Finally, the front desk will no longer handle cash, so please pay for classes by card or through the university app.','TTS','["Classes must be paid for a month ahead.","Class prices will rise in winter.","Bills and coins will not be taken.","Payment can be made only through the app."]','C',1,'"The front desk will no longer handle cash", that is, bills and coins will not be taken. Payment is possible by card or through the app, so the app is not the only way.',86),
(@set09_exam_id,'LISTENING','LISTEN_ANNOUNCEMENT','Listen to an announcement at a student club meeting. Why has the location of the tournament changed?','One quick announcement before we finish. Saturday''s debate tournament has been moved from the auditorium to the law school courtroom because of a scheduling conflict. Registration still opens at nine, but the first round now starts at ten thirty, half an hour later than planned. Volunteers, please arrive by eight thirty to arrange the furniture.','TTS','["The auditorium is being repaired this weekend.","The original room is needed for something else.","More people registered than the auditorium holds.","The law school asked to host the tournament."]','B',1,'The tournament was moved "because of a scheduling conflict": two events were planned for the auditorium at the same time, so the room is needed for something else.',87),
(@set09_exam_id,'LISTENING','LISTEN_ANNOUNCEMENT','Listen to an announcement at a student club meeting. What are volunteers asked to do?','One quick announcement before we finish. Saturday''s debate tournament has been moved from the auditorium to the law school courtroom because of a scheduling conflict. Registration still opens at nine, but the first round now starts at ten thirty, half an hour later than planned. Volunteers, please arrive by eight thirty to arrange the furniture.','TTS','["Come early to set up the room","Register participants at nine","Bring furniture from the auditorium","Wait until the first round begins"]','A',1,'"Volunteers, please arrive by eight thirty to arrange the furniture" — they should come early to set up the room.',88),
(@set09_exam_id,'LISTENING','LISTEN_ANNOUNCEMENT','Listen to an announcement at a student club meeting. What does the speaker say about the first round?','One quick announcement before we finish. Saturday''s debate tournament has been moved from the auditorium to the law school courtroom because of a scheduling conflict. Registration still opens at nine, but the first round now starts at ten thirty, half an hour later than planned. Volunteers, please arrive by eight thirty to arrange the furniture.','TTS','["It will last only half an hour.","It will still be held in the auditorium.","It has been postponed until Sunday.","It will begin later than originally planned."]','D',1,'The first round "now starts at ten thirty, half an hour later than planned".',89),
(@set09_exam_id,'LISTENING','LISTEN_TALK','Listen to a talk in a linguistics class. What is the main topic of the talk?','Professor: Today I''d like to examine loanwords, which are vocabulary items that one language adopts from another, and the motivations behind this borrowing. English contains thousands of them: piano originated in Italian, kindergarten in German, and tsunami in Japanese. The most obvious motivation is necessity. When speakers encounter an unfamiliar object or concept, adopting the foreign name is usually more convenient than inventing a replacement, which explains how coffee and tomato entered English together with the products themselves. Necessity, however, cannot account for everything, because languages sometimes borrow words for which they already possess perfectly adequate equivalents. After the Normans conquered England in ten sixty-six, French became the language of the aristocracy, and its vocabulary acquired considerable prestige, meaning the social admiration attached to a particular way of speaking. Consequently, English retained its original word cow for the animal in the field but adopted the French-derived word beef for the meat served at the table. Notice also what happens afterward through a process linguists call assimilation: the pronunciation and grammar of a borrowed word are gradually reshaped until speakers no longer perceive it as foreign. Few English speakers recognize window as a Scandinavian contribution, for instance. Next, we''ll consider the opposite situation, namely communities that deliberately resist borrowing and construct native alternatives instead.','TTS','["How English spread to other parts of the world","The consequences of the Norman conquest of England","Why and how languages take words from one another","Why some languages are harder to learn than others"]','C',1,'The professor defines loanwords, gives two motivations for borrowing (necessity and prestige) and describes how borrowed words are assimilated — why and how languages take words from one another.',90),
(@set09_exam_id,'LISTENING','LISTEN_TALK','Listen to a talk in a linguistics class. According to the professor, why did words like "coffee" and "tomato" enter English?','Professor: Today I''d like to examine loanwords, which are vocabulary items that one language adopts from another, and the motivations behind this borrowing. English contains thousands of them: piano originated in Italian, kindergarten in German, and tsunami in Japanese. The most obvious motivation is necessity. When speakers encounter an unfamiliar object or concept, adopting the foreign name is usually more convenient than inventing a replacement, which explains how coffee and tomato entered English together with the products themselves. Necessity, however, cannot account for everything, because languages sometimes borrow words for which they already possess perfectly adequate equivalents. After the Normans conquered England in ten sixty-six, French became the language of the aristocracy, and its vocabulary acquired considerable prestige, meaning the social admiration attached to a particular way of speaking. Consequently, English retained its original word cow for the animal in the field but adopted the French-derived word beef for the meat served at the table. Notice also what happens afterward through a process linguists call assimilation: the pronunciation and grammar of a borrowed word are gradually reshaped until speakers no longer perceive it as foreign. Few English speakers recognize window as a Scandinavian contribution, for instance. Next, we''ll consider the opposite situation, namely communities that deliberately resist borrowing and construct native alternatives instead.','TTS','["They sounded more elegant than the English equivalents.","They named things that were new to English speakers.","They were easier to pronounce than older words.","They were required at the court of the aristocracy."]','B',1,'These are the professor''s examples of borrowing from necessity: the words entered English "together with the products themselves", which were unfamiliar to English speakers.',91),
(@set09_exam_id,'LISTENING','LISTEN_TALK','Listen to a talk in a linguistics class. Why does the professor mention the words "cow" and "beef"?','Professor: Today I''d like to examine loanwords, which are vocabulary items that one language adopts from another, and the motivations behind this borrowing. English contains thousands of them: piano originated in Italian, kindergarten in German, and tsunami in Japanese. The most obvious motivation is necessity. When speakers encounter an unfamiliar object or concept, adopting the foreign name is usually more convenient than inventing a replacement, which explains how coffee and tomato entered English together with the products themselves. Necessity, however, cannot account for everything, because languages sometimes borrow words for which they already possess perfectly adequate equivalents. After the Normans conquered England in ten sixty-six, French became the language of the aristocracy, and its vocabulary acquired considerable prestige, meaning the social admiration attached to a particular way of speaking. Consequently, English retained its original word cow for the animal in the field but adopted the French-derived word beef for the meat served at the table. Notice also what happens afterward through a process linguists call assimilation: the pronunciation and grammar of a borrowed word are gradually reshaped until speakers no longer perceive it as foreign. Few English speakers recognize window as a Scandinavian contribution, for instance. Next, we''ll consider the opposite situation, namely communities that deliberately resist borrowing and construct native alternatives instead.','TTS','["To illustrate borrowing that is motivated by social status","To show that English has lost most of its original vocabulary","To explain how farming changed after the Norman conquest","To prove that French grammar reshaped English"]','A',1,'English already had a word, yet adopted the French-derived one because French vocabulary had "acquired considerable prestige" — borrowing motivated by social status.',92),
(@set09_exam_id,'LISTENING','LISTEN_TALK','Listen to a talk in a linguistics class. What will the professor discuss next?','Professor: Today I''d like to examine loanwords, which are vocabulary items that one language adopts from another, and the motivations behind this borrowing. English contains thousands of them: piano originated in Italian, kindergarten in German, and tsunami in Japanese. The most obvious motivation is necessity. When speakers encounter an unfamiliar object or concept, adopting the foreign name is usually more convenient than inventing a replacement, which explains how coffee and tomato entered English together with the products themselves. Necessity, however, cannot account for everything, because languages sometimes borrow words for which they already possess perfectly adequate equivalents. After the Normans conquered England in ten sixty-six, French became the language of the aristocracy, and its vocabulary acquired considerable prestige, meaning the social admiration attached to a particular way of speaking. Consequently, English retained its original word cow for the animal in the field but adopted the French-derived word beef for the meat served at the table. Notice also what happens afterward through a process linguists call assimilation: the pronunciation and grammar of a borrowed word are gradually reshaped until speakers no longer perceive it as foreign. Few English speakers recognize window as a Scandinavian contribution, for instance. Next, we''ll consider the opposite situation, namely communities that deliberately resist borrowing and construct native alternatives instead.','TTS','["Words that English has given to other languages","How the pronunciation of loanwords is reshaped","The Scandinavian origin of everyday vocabulary","Communities that avoid taking in foreign words"]','D',1,'The talk ends: "Next, we''ll consider ... communities that deliberately resist borrowing and construct native alternatives instead."',93),
(@set09_exam_id,'LISTENING','LISTEN_TALK','Listen to a talk on a podcast about architecture. What is the talk mainly about?','Woman: Welcome back to the podcast. Today''s subject is the windcatcher, a ventilation tower that cools buildings without electricity and has existed in some form for thousands of years. Visitors to the desert cities of central Iran will notice tall brick towers rising above the rooftops, each with openings near the summit that face the prevailing wind, which is the direction from which air most frequently blows. Moving air is captured, channeled down a vertical shaft, and distributed through the rooms below. Remarkably, the tower continues functioning on completely windless days, although the circulation reverses. Sunlight heats the masonry, the warm air inside rises and escapes through the openings, and this movement draws cooler replacement air into the house from shaded courtyards. Engineers describe this as passive cooling, meaning temperature control that requires no mechanical equipment. In many traditional houses, the incoming air first travels across an underground water channel, where evaporation reduces its temperature even further. So why were windcatchers abandoned? Primarily because air conditioners became available and were inexpensive to install. Air conditioning, however, now consumes an increasing proportion of the world''s electricity, and architects are reconsidering the older technology. Several contemporary office buildings in hot climates incorporate modernized versions of the tower, and I''ll describe two of them after the break.','TTS','["The history of desert cities in central Iran","A traditional method of cooling buildings","The environmental cost of air conditioning","How underground water channels are constructed"]','B',1,'The speaker introduces the windcatcher as a very old ventilation tower that cools buildings without electricity and explains how it works — a traditional method of cooling buildings.',94),
(@set09_exam_id,'LISTENING','LISTEN_TALK','Listen to a talk on a podcast about architecture. According to the speaker, how does a windcatcher work when there is no wind?','Woman: Welcome back to the podcast. Today''s subject is the windcatcher, a ventilation tower that cools buildings without electricity and has existed in some form for thousands of years. Visitors to the desert cities of central Iran will notice tall brick towers rising above the rooftops, each with openings near the summit that face the prevailing wind, which is the direction from which air most frequently blows. Moving air is captured, channeled down a vertical shaft, and distributed through the rooms below. Remarkably, the tower continues functioning on completely windless days, although the circulation reverses. Sunlight heats the masonry, the warm air inside rises and escapes through the openings, and this movement draws cooler replacement air into the house from shaded courtyards. Engineers describe this as passive cooling, meaning temperature control that requires no mechanical equipment. In many traditional houses, the incoming air first travels across an underground water channel, where evaporation reduces its temperature even further. So why were windcatchers abandoned? Primarily because air conditioners became available and were inexpensive to install. Air conditioning, however, now consumes an increasing proportion of the world''s electricity, and architects are reconsidering the older technology. Several contemporary office buildings in hot climates incorporate modernized versions of the tower, and I''ll describe two of them after the break.','TTS','["Electric fans push air down the vertical shaft.","Water evaporates from the summit of the tower.","Heated air leaving the tower draws in cooler air.","The openings near the summit are sealed shut."]','C',1,'On windless days sunlight heats the masonry, "the warm air inside rises and escapes through the openings, and this movement draws cooler replacement air into the house".',95),
(@set09_exam_id,'LISTENING','LISTEN_TALK','Listen to a talk on a podcast about architecture. Why does the speaker mention an underground water channel?','Woman: Welcome back to the podcast. Today''s subject is the windcatcher, a ventilation tower that cools buildings without electricity and has existed in some form for thousands of years. Visitors to the desert cities of central Iran will notice tall brick towers rising above the rooftops, each with openings near the summit that face the prevailing wind, which is the direction from which air most frequently blows. Moving air is captured, channeled down a vertical shaft, and distributed through the rooms below. Remarkably, the tower continues functioning on completely windless days, although the circulation reverses. Sunlight heats the masonry, the warm air inside rises and escapes through the openings, and this movement draws cooler replacement air into the house from shaded courtyards. Engineers describe this as passive cooling, meaning temperature control that requires no mechanical equipment. In many traditional houses, the incoming air first travels across an underground water channel, where evaporation reduces its temperature even further. So why were windcatchers abandoned? Primarily because air conditioners became available and were inexpensive to install. Air conditioning, however, now consumes an increasing proportion of the world''s electricity, and architects are reconsidering the older technology. Several contemporary office buildings in hot climates incorporate modernized versions of the tower, and I''ll describe two of them after the break.','TTS','["To describe a feature that makes the cooling stronger","To explain how traditional houses obtained drinking water","To show why the towers had to be built so tall","To give a reason that windcatchers were abandoned"]','A',1,'Air traveling across the water channel has its temperature reduced "even further" by evaporation — the channel is a feature that makes the cooling stronger.',96),
(@set09_exam_id,'LISTENING','LISTEN_TALK','Listen to a talk on a podcast about architecture. What does the speaker imply about windcatchers today?','Woman: Welcome back to the podcast. Today''s subject is the windcatcher, a ventilation tower that cools buildings without electricity and has existed in some form for thousands of years. Visitors to the desert cities of central Iran will notice tall brick towers rising above the rooftops, each with openings near the summit that face the prevailing wind, which is the direction from which air most frequently blows. Moving air is captured, channeled down a vertical shaft, and distributed through the rooms below. Remarkably, the tower continues functioning on completely windless days, although the circulation reverses. Sunlight heats the masonry, the warm air inside rises and escapes through the openings, and this movement draws cooler replacement air into the house from shaded courtyards. Engineers describe this as passive cooling, meaning temperature control that requires no mechanical equipment. In many traditional houses, the incoming air first travels across an underground water channel, where evaporation reduces its temperature even further. So why were windcatchers abandoned? Primarily because air conditioners became available and were inexpensive to install. Air conditioning, however, now consumes an increasing proportion of the world''s electricity, and architects are reconsidering the older technology. Several contemporary office buildings in hot climates incorporate modernized versions of the tower, and I''ll describe two of them after the break.','TTS','["They are too expensive to construct now.","They are of historical interest only.","They function only in the climate of Iran.","Their design is becoming relevant again."]','D',1,'Because of the electricity consumed by air conditioning, "architects are reconsidering the older technology" and new buildings incorporate modernized versions of the tower — the design is becoming relevant again.',97);
INSERT INTO tp_questions (exam_id, section, task_type, prompt, body_text, audio_mode, choices_json, answer_key, auto_score, explanation, order_no) VALUES
(@set09_exam_id,'WRITING','BUILD_SENTENCE','Make an appropriate sentence. Use every word once. — A: "Did the inspector say anything before he left?" — B: "Yes. He asked _____."',NULL,'NONE','["wiring","had","whether","replaced","the","been"]','whether the wiring had been replaced',1,'Full reply: He asked whether the wiring had been replaced. A reported yes/no question uses whether + subject (the wiring) + verb (had been replaced), with no inversion.',98),
(@set09_exam_id,'WRITING','BUILD_SENTENCE','Make an appropriate sentence. Use every word once. — A: "I finally finished painting the spare bedroom." — B: "_____?"',NULL,'NONE','["job","did","take","how","whole","the","long"]','how long did the whole job take',1,'Full reply: How long did the whole job take? A direct question about duration is How long + did + subject (the whole job) + base verb (take).',99),
(@set09_exam_id,'WRITING','BUILD_SENTENCE','Make an appropriate sentence. Use every word once. — A: "Do you know which room our seminar is in next week?" — B: "No. I _____ yet."',NULL,'NONE','["received","the","not","schedule","have","revised"]','have not received the revised schedule',1,'Full reply: I have not received the revised schedule yet. A negative present perfect is have + not + past participle (received), followed by the object (the revised schedule).',100),
(@set09_exam_id,'WRITING','BUILD_SENTENCE','Make an appropriate sentence. Use every word once. — A: "Which hiking trail should we take on Sunday?" — B: "Let''s try the one _____."',NULL,'NONE','["were","about","your","that","talking","coworkers"]','that your coworkers were talking about',1,'Full reply: Let''s try the one that your coworkers were talking about. The relative clause is that + subject (your coworkers) + verb (were talking) + the preposition about left at the end.',101),
(@set09_exam_id,'WRITING','BUILD_SENTENCE','Make an appropriate sentence. Use every word once. — A: "The printer on the second floor is broken again." — B: "_____ to repair it?"',NULL,'NONE','["technician","is","back","when","coming","the"]','when is the technician coming back',1,'Full reply: When is the technician coming back to repair it? A direct wh-question puts the verb before the subject: When + is + the technician + coming back.',102),
(@set09_exam_id,'WRITING','BUILD_SENTENCE','Make an appropriate sentence. Use every word once. — A: "I''m thinking about taking the evening Spanish course." — B: "Can you tell me _____?"',NULL,'NONE','["open","course","to","whether","beginners","the","is"]','whether the course is open to beginners',1,'Full reply: Can you tell me whether the course is open to beginners? After tell me, the embedded question is whether + subject (the course) + verb (is) + open to beginners.',103),
(@set09_exam_id,'WRITING','BUILD_SENTENCE','Make an appropriate sentence. Use every word once. — A: "How did you get such a good price on your flight?" — B: "I booked it _____."',NULL,'NONE','["sale","as","was","the","soon","announced","as"]','as soon as the sale was announced',1,'Full reply: I booked it as soon as the sale was announced. The time clause is as soon as + subject (the sale) + passive verb (was announced).',104),
(@set09_exam_id,'WRITING','BUILD_SENTENCE','Make an appropriate sentence. Use every word once. — A: "Why didn''t you come to the picnic on Sunday?" — B: "Nobody told me _____."',NULL,'NONE','["going","held","where","to","it","be","was"]','where it was going to be held',1,'Full reply: Nobody told me where it was going to be held. The embedded question keeps statement order: where + it + was going to + be held (passive).',105),
(@set09_exam_id,'WRITING','WRITE_EMAIL','Write an Email (7 minutes). Read the information below and write the email. Include as much detail as you can and use complete sentences.','You ordered a desk lamp from an online store. When the package arrived, the outer box looked perfect, but the glass shade of the lamp was cracked. You need the lamp for your studies next week.\n\nWrite an email to the store''s customer service team. Your email should do three things:\n- Describe the problem with your order.\n- Explain why you believe the damage happened before the package was shipped.\n- Say what you would like the store to do.\n\nTo: Customer Service, Brightroom Home\nSubject: Damaged item in my order','NONE',NULL,NULL,0,'Saved for manual review; TestPrep does not auto-score writing. Check that all three points are covered (the cracked shade, the undamaged box as evidence, a clear request such as a replacement before next week), that the tone is polite and suited to a company, and that sentences are complete and accurate.',106),
(@set09_exam_id,'WRITING','WRITE_EMAIL','Write an Email (7 minutes). Read the information below and write the email. Include as much detail as you can and use complete sentences.','Your neighbor, Mr. Alvarez, has kindly offered to look after your apartment while you are away for two weeks. You have several plants, and a package may be delivered while you are gone.\n\nWrite an email to Mr. Alvarez. Your email should do three things:\n- Thank him for his offer.\n- Explain how he should take care of the plants.\n- Tell him what to do if the package arrives.\n\nTo: Mr. Alvarez\nSubject: While I am away','NONE',NULL,NULL,0,'Saved for manual review; TestPrep does not auto-score writing. Check that all three points are covered (thanks, clear plant-care instructions, what to do with the package), that the tone is friendly but respectful, and that the instructions are specific enough to follow.',107),
(@set09_exam_id,'WRITING','WRITE_DISCUSSION','Write for an Academic Discussion (10 minutes). Your professor is teaching a class on urban planning. Read the discussion below and write a post that responds to the professor''s question. State your opinion and support it, and use your own words to add to the discussion. Write at least 100 words.','Dr. Ramos\nMany cities are turning busy downtown streets into car-free zones that are open only to pedestrians, cyclists, and public transportation. Supporters say these zones reduce pollution and bring more life to city centers. Critics answer that they hurt shops and make daily life harder for people who depend on cars. Should cities close more of their downtown streets to cars? Why or why not?\n\nHannah\nI think cities should create more car-free streets. When my hometown closed its main shopping street to traffic, the cafés put tables outside and more people came downtown on weekends. Cleaner air and less noise are worth a slightly longer walk.\n\nKenji\nI am not convinced. Elderly people and parents with small children often cannot walk far, and delivery trucks still need to reach the stores. If a street is closed, the traffic simply moves to the next one, so the pollution is not really reduced.','NONE',NULL,NULL,0,'Saved for manual review; TestPrep does not auto-score writing. A strong post states a clear position, supports it with a developed reason or example, is written in the student''s own words instead of copying Hannah or Kenji, and reaches 100 words or more with accurate, varied sentences.',108),
(@set09_exam_id,'WRITING','WRITE_DISCUSSION','Write for an Academic Discussion (10 minutes). Your professor is teaching a class on education. Read the discussion below and write a post that responds to the professor''s question. State your opinion and support it, and use your own words to add to the discussion. Write at least 100 words.','Dr. Nwosu\nThis week we are looking at how schools report student progress. Some schools have stopped giving letter grades to younger students and instead send home written comments that describe what each child can do and what needs more work. Others argue that grades are clearer and motivate students to try harder. Do you think written comments should replace letter grades in schools? Why or why not?\n\nAmara\nWritten comments are far more useful. A "B" tells me nothing about what I did well or what I should fix, but two sentences from a teacher can show me exactly where to improve. Grades also make students compare themselves with classmates instead of focusing on learning.\n\nLucas\nI would keep grades. Parents are busy, and a letter is quick to understand. Comments can also be vague, like "good effort," and some students stop trying when nothing is being measured. A grade gives everyone a clear goal.','NONE',NULL,NULL,0,'Saved for manual review; TestPrep does not auto-score writing. A strong post takes a side (or a reasoned middle position), develops at least one reason with an example, is written in the student''s own words instead of copying Amara or Lucas, and reaches 100 words or more.',109);
INSERT INTO tp_questions (exam_id, section, task_type, prompt, body_text, audio_mode, choices_json, answer_key, auto_score, explanation, order_no) VALUES
(@set09_exam_id,'SPEAKING','SPEAK_REPEAT','You are training to work at the information desk of a science museum. Listen to your supervisor and repeat the sentence aloud. Repeat only once. Record your answer.','Welcome to the science museum.','TTS',NULL,NULL,0,'Recorded for manual review. Say every word clearly and stress science museum.',110),
(@set09_exam_id,'SPEAKING','SPEAK_REPEAT','You are training to work at the information desk of a science museum. Listen to your supervisor and repeat the sentence aloud. Repeat only once. Record your answer.','The ticket counter is on your left.','TTS',NULL,NULL,0,'Recorded for manual review. Keep the sentence in one breath and stress ticket counter and left.',111),
(@set09_exam_id,'SPEAKING','SPEAK_REPEAT','You are training to work at the information desk of a science museum. Listen to your supervisor and repeat the sentence aloud. Repeat only once. Record your answer.','Lockers for coats and bags are downstairs.','TTS',NULL,NULL,0,'Recorded for manual review. Pronounce the final s in lockers, coats, and bags.',112),
(@set09_exam_id,'SPEAKING','SPEAK_REPEAT','You are training to work at the information desk of a science museum. Listen to your supervisor and repeat the sentence aloud. Repeat only once. Record your answer.','The planetarium show starts every hour on the hour.','TTS',NULL,NULL,0,'Recorded for manual review. Planetarium has five syllables with the stress on TAR; do not drop the second hour.',113),
(@set09_exam_id,'SPEAKING','SPEAK_REPEAT','You are training to work at the information desk of a science museum. Listen to your supervisor and repeat the sentence aloud. Repeat only once. Record your answer.','Please keep food and drinks out of the exhibition halls.','TTS',NULL,NULL,0,'Recorded for manual review. Group the words: please keep food and drinks / out of the exhibition halls.',114),
(@set09_exam_id,'SPEAKING','SPEAK_REPEAT','You are training to work at the information desk of a science museum. Listen to your supervisor and repeat the sentence aloud. Repeat only once. Record your answer.','If you get lost, look for a staff member in a green vest.','TTS',NULL,NULL,0,'Recorded for manual review. Pause briefly after lost and keep the small words a and in.',115),
(@set09_exam_id,'SPEAKING','SPEAK_REPEAT','You are training to work at the information desk of a science museum. Listen to your supervisor and repeat the sentence aloud. Repeat only once. Record your answer.','Children under twelve must stay with an adult while visiting the laboratory area.','TTS',NULL,NULL,0,'Recorded for manual review. Remember the two halves: who (children under twelve must stay with an adult) and when (while visiting the laboratory area).',116),
(@set09_exam_id,'SPEAKING','SPEAK_REPEAT','You are training to work at the information desk of a science museum. Listen to your supervisor and repeat the sentence aloud. Repeat only once. Record your answer.','To avoid the afternoon crowds, we recommend visiting the dinosaur gallery before eleven o''clock.','TTS',NULL,NULL,0,'Recorded for manual review. This is the longest sentence: hold three chunks in mind (to avoid the afternoon crowds / we recommend visiting the dinosaur gallery / before eleven o''clock).',117),
(@set09_exam_id,'SPEAKING','SPEAK_INTERVIEW','Take an Interview. You are taking part in a university survey about reading habits. Answer the interviewer''s question aloud (about 30-45 seconds). No preparation time is given. Record your answer.','Thank you for joining our survey on reading habits. First, what kind of reading do you do most often in a typical week, and where do you usually do it?','NONE',NULL,NULL,0,'Recorded for manual review. Answer both parts (what you read and where), add a detail or reason, and keep speaking for the full time.',118),
(@set09_exam_id,'SPEAKING','SPEAK_INTERVIEW','Take an Interview. You are taking part in a university survey about reading habits. Answer the interviewer''s question aloud (about 30-45 seconds). No preparation time is given. Record your answer.','I see. Do you think it matters whether a person reads on a screen or on paper? Why or why not?','NONE',NULL,NULL,0,'Recorded for manual review. State your opinion in the first sentence, give one or two reasons, and support them with a personal example.',119),
(@set09_exam_id,'SPEAKING','SPEAK_INTERVIEW','Take an Interview. You are taking part in a university survey about reading habits. Answer the interviewer''s question aloud (about 30-45 seconds). No preparation time is given. Record your answer.','Interesting. Lastly, let''s think about the future. Twenty years from now, do you expect printed books to be as common as they are today, or will most reading happen on screens? Please explain why.','NONE',NULL,NULL,0,'Recorded for manual review. Make a clear prediction about the future, give at least one reason for it, and use future forms (will, be likely to, might) accurately.',120);
